@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a ns1:DefinedTerm ;
                    ns1:alternateName "ATCC 9930",
                        "CCUG 27879",
                        "CFBP 5561",
                        "DSM 30135",
                        "Ensifer meliloti",
                        "Ensifer meliloti (Dangeard 1926) Young 2003",
                        "Ensifer sp. AC50a",
                        "Ensifer sp. AC50e",
                        "HAMBI 2148",
                        "IAM 12611",
                        "ICMP 12623",
                        "IFO 14782",
                        "JCM 20682",
                        "LMG 6133",
                        "LMG:6133",
                        "NBRC 14782",
                        "NCAIM B.01520",
                        "NRRL L-45",
                        "NRRL:L:45",
                        "NZP 4027",
                        "Rhizobium meliloti (megaplasmid pRME41B SYM)",
                        "Rhizobium meliloti (plasmid pRmeGR4b)",
                        "Rhizobium meliloti Dangeard 1926 (Approved Lists 1980)",
                        "Rhizobium meliloti plasmid pRmeGR4b",
                        "Rhizobium sp. AC50e",
                        "Sinorhizobium meliloti (Dangeard 1926) De Lajudie et al. 1994",
                        "USDA 1002" ;
                    ns1:identifier "382" ;
                    ns1:inDefinedTermSet "UniProt" ;
                    ns1:name "Rhizobium meliloti" ;
                    ns1:url "https://www.uniprot.org/taxonomy/382" ;
                    nde:curatedBy [ a ns1:SoftwareApplication ;
                            ns1:dateModified "2024-01-26" ;
                            ns1:name "PubTator" ;
                            ns1:url "https://www.ncbi.nlm.nih.gov/research/pubtator/api.html" ] ;
                    nde:isCurated "yes" ;
                    nde:originalName "Sinorhizobium meliloti" ;
                    ns2:commonName "Ensifer meliloti" ] ;
            sh:resultMessage "nde:isCurated must be a single boolean." ;
            sh:resultPath nde:isCurated ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:DatatypeConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:boolean ;
                    sh:maxCount 1 ;
                    sh:message "nde:isCurated must be a single boolean." ;
                    sh:path nde:isCurated ;
                    sh:severity sh:Violation ] ;
            sh:value "yes" ] .

